import string


class BadgeCodePolicy:
    def __init__(self, symbols="@#%+"):
        if not isinstance(symbols, str) or not symbols or len(set(symbols)) != len(symbols):
            raise ValueError("symbols must be non-empty and distinct")
        if any(character.isalnum() for character in symbols):
            raise ValueError("symbols must be non-alphanumeric")
        self._symbols = symbols

    def assess(self, code):
        if not isinstance(code, str):
            raise TypeError("code must be a string")
        checks = (
            ("uppercase", any(c in string.ascii_uppercase for c in code)),
            ("lowercase", any(c in string.ascii_lowercase for c in code)),
            ("digit", any(c in string.digits for c in code)),
            ("symbol", any(c in self._symbols for c in code)),
        )
        missing = tuple(name for name, present in checks if not present)
        if missing:
            level = "invalid"
        elif len(code) >= 10:
            level = "strong"
        elif len(code) >= 8:
            level = "moderate"
        else:
            level = "weak"
        return {"level": level, "missing": missing}

    def create(self, seed, length=12):
        if not isinstance(seed, str) or not seed:
            raise ValueError("seed must be a non-empty string")
        if isinstance(length, bool) or not isinstance(length, int) or length < 12:
            raise ValueError("length must be an integer of at least 12")

        def first_from(alphabet, fallback):
            return next((c for c in seed if c in alphabet), fallback)

        result = [
            first_from(string.ascii_uppercase, "A"),
            first_from(string.ascii_lowercase, "a"),
            first_from(string.digits, "0"),
            self._symbols[0],
        ]
        pool = seed + self._symbols
        index = 0
        while len(result) < length:
            result.append(pool[index % len(pool)])
            index += 1
        return "".join(result[:length])

